import{_ as t,o as a,c as r,ag as l}from"./chunks/framework.DKalukzk.js";const u=JSON.parse('{"title":"RechercheV","description":"","frontmatter":{"title":"RechercheV"},"headers":[],"relativePath":"modules/02-excel/08-recherche.md","filePath":"modules/02-excel/08-recherche.md"}'),o={name:"modules/02-excel/08-recherche.md"};function c(n,e,s,d,i,h){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="recherchev" tabindex="-1">RechercheV <a class="header-anchor" href="#recherchev" aria-label="Permalink to &quot;RechercheV&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQAuQGQtIzGAQpyW-hccqJkUAUpVEuCiglNK9P1LmxkoQBE?e=0j7J5D" target="_blank" rel="noreferrer">08 – Recherche</a></p><p>⚠️ Ne travaillez pas dans la version Excel du navigateur Web.</p><p><strong>Veuillez télécharger une copie de chaque exercice.</strong></p><ul><li>Fichier --&gt; Créer une copie --&gt; Télécharger une copie</li></ul><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><ul><li>Rechercher rapidement une information dans une liste ou un tableau.</li><li>Éviter de faire des recherches manuelles ligne par ligne.</li><li>Assurer la cohérence des données dans un classeur.</li></ul><h2 id="fonction-recherchev" tabindex="-1">Fonction RECHERCHEV <a class="header-anchor" href="#fonction-recherchev" aria-label="Permalink to &quot;Fonction RECHERCHEV&quot;">​</a></h2><p>Syntaxe de base :</p><p><code>=RECHERCHEV(valeur_recherchée; table_matrice; no_index_col; [valeur_proche])</code></p><ul><li><code>valeur_recherchée</code> : ce que vous cherchez (ex. un code, un nom).</li><li><code>table_matrice</code> : une plage de valeurs, en commençant par la colonne de recherche.</li><li><code>no_index_col</code> : numéro de la colonne à retourner dans le tableau (1 = première colonne, 2 = deuxième, etc.).</li><li><code>[valeur_proche]</code> : VRAI (approx.) ou FAUX (exact). Utiliser FAUX dans ce cours.</li></ul><h2 id="procedure-recherche-exacte" tabindex="-1">Procédure (recherche exacte) <a class="header-anchor" href="#procedure-recherche-exacte" aria-label="Permalink to &quot;Procédure (recherche exacte)&quot;">​</a></h2><ol><li>Placer le curseur dans la cellule où le résultat doit apparaître.</li><li>Taper <code>=RECHERCHEV(</code> ou utiliser l’outil d’insertion de fonctions.</li><li>Sélectionner la valeur recherchée (cellule à gauche ou au-dessus).</li><li>Sélectionner la plage de données complète (en fixant la plage avec les $ si nécessaire : <code>$A$2:$D$20</code>).</li><li>Indiquer le numéro de colonne à retourner (ex. 3 pour la 3e colonne).</li><li>Indiquer FAUX pour obtenir une correspondance exacte.</li><li>Valider avec Entrée, puis recopier la formule si nécessaire.</li></ol><h2 id="exemples" tabindex="-1">Exemples <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples&quot;">​</a></h2><h3 id="rechercher-le-prix-d-un-produit-a-partir-de-son-code" tabindex="-1">Rechercher le prix d’un produit à partir de son code. <a class="header-anchor" href="#rechercher-le-prix-d-un-produit-a-partir-de-son-code" aria-label="Permalink to &quot;Rechercher le prix d’un produit à partir de son code.&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=RECHERCHEV(F1; $A$1:$D$4; 4; FAUX)</span></span></code></pre></div><p>Exemple de feuille Excel (produits) :</p><table tabindex="0"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th></tr></thead><tbody><tr><td>1</td><td><span class="bg-yellow-100">Code produit</span></td><td>Nom</td><td>Catégorie</td><td><span class="bg-yellow-100">Prix</span></td></tr><tr><td>2</td><td><span class="bg-yellow-100">P001</span></td><td>Clavier</td><td>Accessoire</td><td><span class="bg-yellow-100">39,99</span></td></tr><tr><td>3</td><td><span class="bg-yellow-100">P002</span></td><td>Souris</td><td>Accessoire</td><td><span class="bg-yellow-100">24,99</span></td></tr><tr><td>4</td><td><span class="bg-yellow-100">P003</span></td><td>Écran 24&quot;</td><td>Écran</td><td><span class="bg-yellow-100">199,99</span></td></tr></tbody></table><p>Petit tableau de contexte (valeur entrée dans F1) :</p><table tabindex="0"><thead><tr><th></th><th>F</th></tr></thead><tbody><tr><td>1</td><td><span class="bg-yellow-100">P002</span></td></tr></tbody></table><blockquote><p>Quel résultat sera retourné par la fonction RechercheV ci-haut?</p></blockquote><details><summary>Réponse</summary> 24.99$ </details><div class="warning custom-block"><p class="custom-block-title">Explication</p><p>La fonction cherche la valeur de <code>F1</code> (ici <strong>P002</strong>) dans la colonne <strong>A</strong> et retourne le prix correspondant dans la colonne <strong>D</strong> (4<sup>e</sup> colonne de la plage).</p></div><h3 id="rechercher-le-nom-d-un-client-a-partir-de-son-numero" tabindex="-1">Rechercher le nom d’un client à partir de son numéro. <a class="header-anchor" href="#rechercher-le-nom-d-un-client-a-partir-de-son-numero" aria-label="Permalink to &quot;Rechercher le nom d’un client à partir de son numéro.&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=RECHERCHEV(F10; $A$10:$D$13; 2; FAUX)</span></span></code></pre></div><p>Exemple de feuille Excel (clients) :</p><table tabindex="0"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th></tr></thead><tbody><tr><td>10</td><td><span class="bg-yellow-100">No client</span></td><td><span class="bg-yellow-100">Nom complet</span></td><td>Ville</td><td>Solde</td></tr><tr><td>11</td><td><span class="bg-yellow-100">1001</span></td><td><span class="bg-yellow-100">Alex Tremblay</span></td><td>Québec</td><td>120,50</td></tr><tr><td>12</td><td><span class="bg-yellow-100">1002</span></td><td><span class="bg-yellow-100">Samira Lévesque</span></td><td>Montréal</td><td>89,00</td></tr><tr><td>13</td><td><span class="bg-yellow-100">1003</span></td><td><span class="bg-yellow-100">Hugo Gagnon</span></td><td>Trois-Rivières</td><td>0,00</td></tr></tbody></table><p>Petit tableau de contexte (valeur entrée dans F10) :</p><table tabindex="0"><thead><tr><th></th><th>F</th></tr></thead><tbody><tr><td>10</td><td><span class="bg-yellow-100">1002</span></td></tr></tbody></table><blockquote><p>Quel résultat sera retourné par la fonction RechercheV ci-haut?</p></blockquote><details><summary>Réponse</summary> Samira Lévesque </details><div class="warning custom-block"><p class="custom-block-title">Explication</p><p>La fonction cherche la valeur de <code>F10</code> (ici <strong>1002</strong>) dans la colonne <strong>A</strong> et retourne le nom du client dans la colonne <strong>B</strong> (2<sup>e</sup> colonne de la plage).</p></div>',33)])])}const b=t(o,[["render",c]]);export{u as __pageData,b as default};
